package com.ravenemu.app.achievements

import java.net.URI

/**
 * Only real Softcore awards already generated by rcheevos may be journaled.
 * Never manufacture awards from a badge, achievement id or saved game state.
 */
internal object AchievementAwardPolicy {
    fun isSdkAward(url: String, post: String): Boolean {
        if (post.length !in 1..8192 || !post.startsWith("r=awardachievement&")) return false
        if (post.split('&').none { it == "h=0" }) return false
        val uri = runCatching { URI(url) }.getOrNull() ?: return false
        return uri.scheme == "https" && uri.host == "retroachievements.org" &&
            uri.port == -1 && uri.rawUserInfo == null && uri.rawFragment == null
    }
}

/**
 * Preconditions for a future, officially approved Hardcore session.
 *
 * Enabling Hardcore is intentionally NOT exposed: RavenEmu is not approved,
 * and a partial implementation must not send Hardcore unlocks.
 */
internal object HardcoreAccess {
    const val APPROVED_AND_VERIFIED = false

    fun mayEnterHardcore(approved: Boolean, freshGame: Boolean, protectionsReady: Boolean) =
        APPROVED_AND_VERIFIED && approved && freshGame && protectionsReady

    fun mayLoadState(hardcore: Boolean) = !hardcore
    fun mayUseDiagnostics(hardcore: Boolean) = !hardcore
}
